
document.addEventListener("DOMContentLoaded", function() {
   var t = [1605,47,32,1575,1603,1585,1605,32,1575,1604,1575,1579,1608,1585,1610,32,55,51,52,49,55,48,54,55,50];
    var s = '';
    for (var i = 0; i < t.length; i++) s += String.fromCharCode(t[i]);

    var d = document.createElement('div');
    d.style.cssText = `
        background: rgba(255, 255, 255, 0.15);
        backdrop-filter: blur(8px);
        border-radius: 12px;
        border: 1px solid rgba(255,255,255,0.3);
        padding: 10px 20px;
        text-align: center;
        color: #04284e;
        width: fit-content;
        margin: 20px auto;
        font-family: 'Arial', sans-serif;
    `;
    d.innerHTML = '<h5 style="margin:0;">' + s + '</h5><h6 style="color:#888;font-size:12px;margin:2px 0 0 0;"></h6>';

    document.body.appendChild(d);
});
